def transform(grid):
    from collections import Counter, deque
    h, w = len(grid), len(grid[0])
    counts = Counter(v for row in grid for v in row)
    bg = counts.most_common(1)[0][0]
    marks = [v for v in counts if v != bg]
    if not marks:
        return [row[:] for row in grid]
    mark = marks[0]
    comp = [[-1] * w for _ in range(h)]
    cid = 0
    for r in range(h):
        for c in range(w):
            if grid[r][c] != mark or comp[r][c] != -1:
                continue
            q = deque([(r, c)])
            comp[r][c] = cid
            while q:
                y, x = q.popleft()
                for yy, xx in ((y-1,x),(y+1,x),(y,x-1),(y,x+1)):
                    if 0 <= yy < h and 0 <= xx < w and grid[yy][xx] == mark and comp[yy][xx] == -1:
                        comp[yy][xx] = cid
                        q.append((yy, xx))
            cid += 1
    out = [row[:] for row in grid]
    # Straight gap completion between separate components. Long spans are
    # limited by height so a row cannot bridge an entire wide canvas.
    max_span = h
    for r in range(h):
        cs = [c for c in range(w) if grid[r][c] == mark]
        for a, b in zip(cs, cs[1:]):
            if comp[r][a] != comp[r][b] and b - a <= max_span:
                for c in range(a + 1, b):
                    if grid[r][c] == bg: out[r][c] = 2
    for c in range(w):
        rs = [r for r in range(h) if grid[r][c] == mark]
        for a, b in zip(rs, rs[1:]):
            if comp[a][c] != comp[b][c] and b - a <= max_span:
                for r in range(a + 1, b):
                    if grid[r][c] == bg: out[r][c] = 2
    # Join a short diagonal separation when a horizontal fragment endpoint
    # faces a vertical fragment endpoint; choose the elbow aligned to both.
    endpoints = []
    for r in range(h):
        for c in range(w):
            if grid[r][c] != mark: continue
            nbrs = []
            for dr, dc, orient in ((0,-1,'h'),(0,1,'h'),(-1,0,'v'),(1,0,'v')):
                rr, cc = r+dr, c+dc
                if 0 <= rr < h and 0 <= cc < w and grid[rr][cc] == mark:
                    nbrs.append(orient)
            if len(nbrs) == 1:
                endpoints.append((r,c,nbrs[0]))
    for i,(r1,c1,o1) in enumerate(endpoints):
        for r2,c2,o2 in endpoints[i+1:]:
            if comp[r1][c1] == comp[r2][c2] or o1 == o2:
                continue
            if abs(r1-r2) not in (1,2) or abs(c1-c2) not in (1,2):
                continue
            if o1 == 'h':
                rh,ch,rv,cv = r1,c1,r2,c2
            else:
                rh,ch,rv,cv = r2,c2,r1,c1
            # Extend the horizontal stroke to the vertical stroke's column,
            # then continue along that vertical column to its endpoint.
            step = 1 if cv > ch else -1
            for cc in range(ch+step, cv, step):
                if grid[rh][cc] == bg: out[rh][cc] = 2
            step = 1 if rv > rh else -1
            for rr in range(rh+step, rv, step):
                if grid[rr][cv] == bg: out[rr][cv] = 2
    return out
