    h, w = len(grid), len(grid[0])
    counts = Counter(v for row in grid for v in row)
    background = counts.most_common(1)[0][0]
    color = next(v for v in counts if v != background)
    labels = [[-1] * w for _ in range(h)]
    component = 0
    for r in range(h):
        for c in range(w):
            if grid[r][c] != color or labels[r][c] != -1:
                continue
            q = deque([(r, c)])
            labels[r][c] = component
            while q:
                y, x = q.popleft()
                for yy, xx in ((y-1,x),(y+1,x),(y,x-1),(y,x+1)):
                    if 0 <= yy < h and 0 <= xx < w and grid[yy][xx] == color and labels[yy][xx] == -1:
                        labels[yy][xx] = component
                        q.append((yy, xx))
            component += 1
    out = [row[:] for row in grid]
    # Interpolate aligned marks only when they belong to different original
    # 4-connected strokes. This preserves intact hollow/closed shapes.
    for r in range(h):
        cols = [c for c in range(w) if grid[r][c] == color]
        for a, b in zip(cols, cols[1:]):
            if labels[r][a] != labels[r][b]:
                for c in range(a+1, b):
                    if grid[r][c] == background:
                        out[r][c] = 2
    for c in range(w):
        rows = [r for r in range(h) if grid[r][c] == color]
        for a, b in zip(rows, rows[1:]):
            if labels[a][c] != labels[b][c]:
                for r in range(a+1, b):
                    if grid[r][c] == background:
                        out[r][c] = 2
    return out
