def transform(grid):
    from collections import Counter, deque
    h, w = len(grid), len(grid[0])
    counts = Counter(v for row in grid for v in row)
    bg = counts.most_common(1)[0][0]
    mark = next(v for v in counts if v != bg)
    labels = [[-1] * w for _ in range(h)]
    cid = 0
    for r in range(h):
        for c in range(w):
            if grid[r][c] != mark or labels[r][c] != -1:
                continue
            q = deque([(r, c)])
            labels[r][c] = cid
            while q:
                y, x = q.popleft()
                for yy, xx in ((y-1,x),(y+1,x),(y,x-1),(y,x+1)):
                    if 0 <= yy < h and 0 <= xx < w and grid[yy][xx] == mark and labels[yy][xx] == -1:
                        labels[yy][xx] = cid
                        q.append((yy, xx))
            cid += 1
    out = [row[:] for row in grid]
    # Fill aligned gaps between distinct stroke fragments, limiting the span
    # to the grid's shorter dimension so distant boundaries are not joined.
    limit = min(h, w)
    for r in range(h):
        cols = [c for c in range(w) if grid[r][c] == mark]
        for a, b in zip(cols, cols[1:]):
            if labels[r][a] != labels[r][b] and b-a <= limit:
                for c in range(a+1, b):
                    if grid[r][c] == bg:
                        out[r][c] = 2
    for c in range(w):
        rows = [r for r in range(h) if grid[r][c] == mark]
        for a, b in zip(rows, rows[1:]):
            if labels[a][c] != labels[b][c] and b-a <= limit:
                for r in range(a+1, b):
                    if grid[r][c] == bg:
                        out[r][c] = 2
    return out
